_RULES = {
    "quartz": ({"quartz.mod"}, (".qproj",)),
    "ember": ({"ember.lock"}, ()),
    "orbit": ({"orbit.map"}, (".orb",)),
}


def _path_parts(path, allow_root):
    if not isinstance(path, str):
        raise TypeError("paths must be strings")
    if not path.startswith("/"):
        raise ValueError("path must be absolute")
    if path == "/":
        if allow_root:
            return []
        raise ValueError("document path must contain a filename")
    parts = path[1:].split("/")
    if any(part in {"", ".", ".."} for part in parts):
        raise ValueError("path must be normalized")
    return parts


def nearest_bundle(document_path, profile, entries):
    document_parts = _path_parts(document_path, False)
    if not isinstance(profile, str):
        raise TypeError("profile must be a string")
    if profile not in _RULES:
        raise ValueError("unknown profile")
    if not isinstance(entries, set):
        raise TypeError("entries must be a set")

    normalized_entries = set()
    for entry in entries:
        _path_parts(entry, True)
        normalized_entries.add(entry)

    directory_parts = document_parts[:-1]
    directories = [
        "/" + "/".join(directory_parts[:length]) if length else "/"
        for length in range(len(directory_parts), -1, -1)
    ]

    exact, suffixes = _RULES[profile]
    for directory in directories:
        prefix = directory.rstrip("/") + "/"
        for entry in normalized_entries:
            if not entry.startswith(prefix):
                continue
            remainder = entry[len(prefix):]
            if "/" not in remainder and (remainder in exact or remainder.endswith(suffixes)):
                return directory

    for directory in directories:
        marker = directory.rstrip("/") + "/.anchor"
        if marker in normalized_entries:
            return directory

    return directories[0]
